class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  final GlobalKey<CurrencyListPageState> _currencyKey = GlobalKey();
  final GlobalKey<NewsListPageState> _newsKey = GlobalKey();

  bool _isRefreshing = false;

  static const List<Widget> _pages = <Widget>[
    CurrencyListPage(key: ValueKey('currency')),
    NewsListPage(key: ValueKey('news')),
    ProfilePage(),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  Future<void> _refreshAll() async {
    if (_isRefreshing) return;
    setState(() => _isRefreshing = true);

    final CurrencyListPageState? currencyState = _currencyKey.currentState;
    final NewsListPageState? newsState = _newsKey.currentState;

    await Future.wait(<Future<void>>[
      currencyState?.refresh() ?? Future<void>.value(),
      newsState?.refresh() ?? Future<void>.value(),
    ]);

    if (mounted) {
      setState(() => _isRefreshing = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      body: currentPage,
      floatingActionButton: FloatingActionButton(
        onPressed: _isRefreshing ? null : _refreshAll,
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 200),
          switchInCurve: Curves.easeInOut,
          switchOutCurve: Curves.easeInOut,
          child: _isRefreshing
              ? SizedBox(
                  key: ValueKey<bool>(true),
                  width: 24,
                  height: 24,
                  child: CircularProgressIndicator(strokeWidth: 2.0),
                )
              : Icon(Icons.refresh, key: ValueKey<bool>(false)),
        ),
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: [
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: currentPage is CurrencyListPage,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: currentPage is NewsListPage,
              ),
              label: loc.news,
            ),
            BottomNavigationBarItem(
              icon: Icon(Icons.person),
              label: loc.profile,
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}
